<?php define('IN_CRONLITE',true);define('SYSTEM_ROOT',dirname(__FILE__).'/');define('ROOT',dirname(dirname(SYSTEM_ROOT)).'/');require_once(ROOT.'includes/common.php');require_once(ROOT.'includes/auth.php');require_login();require_role(['admin','auditor']);$type=$_GET['type']??'pending';$where=$type=='pending'?'WHERE status=1':($type=='passed'?'WHERE status=2':'WHERE status=3');$items=$DB->query("SELECT * FROM ad_creatives $where ORDER BY created_at DESC LIMIT 50")->fetchAll();include(ROOT.'admin/admin.php');?>
<div class="card"><div class="card-header"><h5><i class="fa fa-shield-alt"></i> 广告审核</h5></div><div class="card-body"><div class="mb-3"><a href="?type=pending" class="btn <?=($type=='pending')?'btn-primary':'btn-secondary'?>">待审核</a> <a href="?type=passed" class="btn <?=($type=='passed')?'btn-primary':'btn-secondary'?>">已通过</a> <a href="?type=rejected" class="btn <?=($type=='rejected')?'btn-primary':'btn-secondary'?>">已驳回</a></div><?php foreach($items as $i):?><div class="card mb-3"><div class="card-body"><h6><?=$i['title']?></h6><img src="<?=$i['image_url']?>" style="max-height:200px"><p><?=$i['description']?></p><?php if($type=='pending'):?><button class="btn btn-success btn-sm" onclick="audit(<?=$i['id']?>,2)">通过</button> <button class="btn btn-danger btn-sm" onclick="audit(<?=$i['id']?>,3)">驳回</button><?php endif;?></div></div><?php endforeach;?></div></div><script>function audit(id,status){fetch('/api/audit_ad.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:id,status:status})}).then(r=>r.json()).then(res=>{if(res.code==0)location.reload();else alert(res.msg)})}</script>
